using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class SignpostBuild {public static string Run(){
if(EditorApplication.isPlaying||EditorApplication.isCompiling)throw new Exception("Editor must be idle.");
var before=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).Select(s=>s.path+":"+s.isDirty).ToArray();
var src=new Texture2D(2,2,TextureFormat.RGBA32,false);src.LoadImage(File.ReadAllBytes(@"C:/Users/PCUser/Downloads/上向きと右向きの道標スプライト-pixel-snapper.png"));var px=src.GetPixels32();
if(!px.Any(p=>p.a==0))throw new Exception("Source has no transparency.");
string art="Assets/Art/Environment/Signposts";string pref="Assets/Prefabs/Environment/Signposts";
foreach(string folder in new[]{art,pref}){string p="Assets";foreach(var part in folder.Substring(7).Split('/')){string n=p+"/"+part;if(!AssetDatabase.IsValidFolder(n))AssetDatabase.CreateFolder(p,part);p=n;}}
var report=new List<string>();int split=Mathf.RoundToInt(src.width*.43f);
for(int i=0;i<2;i++){
string name=i==0?"Signpost_Up":"Signpost_Right";string path=art+"/"+name+".png";string prefab=pref+"/"+name+".prefab";if(File.Exists(path)||File.Exists(prefab))throw new Exception("Already exists "+name);
int minX=src.width,minY=src.height,maxX=-1,maxY=-1;int start=i==0?0:split,end=i==0?split:src.width;
for(int y=0;y<src.height;y++)for(int x=start;x<end;x++){if(px[y*src.width+x].a==0)continue;minX=Math.Min(minX,x);minY=Math.Min(minY,y);maxX=Math.Max(maxX,x);maxY=Math.Max(maxY,y);}
if(maxX<minX)throw new Exception("Empty image "+name);
var crop=new Texture2D(maxX-minX+1,maxY-minY+1,TextureFormat.RGBA32,false);crop.SetPixels(src.GetPixels(minX,minY,crop.width,crop.height));crop.Apply();File.WriteAllBytes(path,crop.EncodeToPNG());UnityEngine.Object.DestroyImmediate(crop);
AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);
var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spriteImportMode=SpriteImportMode.Single;imp.spritePixelsPerUnit=100;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.alphaIsTransparency=true;imp.wrapMode=TextureWrapMode.Clamp;imp.npotScale=TextureImporterNPOTScale.None;
var st=new TextureImporterSettings();imp.ReadTextureSettings(st);st.spriteAlignment=(int)SpriteAlignment.BottomCenter;st.spritePivot=new Vector2(.5f,0);st.spriteMeshType=SpriteMeshType.FullRect;imp.SetTextureSettings(st);imp.SaveAndReimport();
var go=EditorUtility.CreateGameObjectWithHideFlags(name,HideFlags.HideAndDontSave,typeof(SpriteRenderer));
try{go.transform.localScale=new Vector3(2,2,1);var sr=go.GetComponent<SpriteRenderer>();sr.sprite=AssetDatabase.LoadAssetAtPath<Sprite>(path);sr.sortingOrder=1;go.hideFlags=HideFlags.None;PrefabUtility.SaveAsPrefabAsset(go,prefab);}finally{UnityEngine.Object.DestroyImmediate(go);}
var saved=AssetDatabase.LoadAssetAtPath<GameObject>(prefab);if(saved.GetComponent<SpriteRenderer>().sprite==null||saved.GetComponent<Collider2D>()!=null)throw new Exception("Invalid prefab");report.Add(name+" "+(maxX-minX+1)+"x"+(maxY-minY+1)+"px");
}
UnityEngine.Object.DestroyImmediate(src);AssetDatabase.SaveAssets();
var after=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).Select(s=>s.path+":"+s.isDirty).ToArray();if(!before.SequenceEqual(after))throw new Exception("Scene dirty state changed");
return string.Join("\n",report)+"\nScene dirty state preserved. CompilationFailed="+EditorUtility.scriptCompilationFailed;
}}
